from collections import OrderedDict
import threading
import time
from typing import Any, Optional, Tuple


class TimeBoundedLRUCache:
    """A thread-safe LRU cache with time-to-live (TTL) expiration per entry."""

    def __init__(self, capacity: int, default_ttl_seconds: float = 60.0) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be a positive integer")
        self.capacity: int = capacity
        self.default_ttl_seconds: float = float(default_ttl_seconds)
        self._cache: OrderedDict[str, Tuple[Any, float]] = OrderedDict()
        self._lock: threading.RLock = threading.RLock()
        self.lock: threading.RLock = self._lock

    def _is_expired(self, expires_at: float, now: Optional[float] = None) -> bool:
        current_time = time.time() if now is None else now
        return current_time >= expires_at

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        """Inserts or updates a key with an optional custom TTL (in seconds).

        If capacity is reached when inserting a new key, expired items are
        evicted first; if still at capacity, the least recently used
        non-expired item is evicted.
        """
        effective_ttl = self.default_ttl_seconds if ttl is None else float(ttl)
        now = time.time()
        expires_at = now + effective_ttl

        with self._lock:
            if key in self._cache:
                self._cache[key] = (value, expires_at)
                self._cache.move_to_end(key)
                return

            if len(self._cache) >= self.capacity:
                self.cleanup_expired()

            while len(self._cache) >= self.capacity:
                self._cache.popitem(last=False)

            self._cache[key] = (value, expires_at)
            self._cache.move_to_end(key)

    def get(self, key: str) -> Optional[Any]:
        """Returns the value for key if present and not expired, else None.

        Accessing a valid key updates its LRU recency.
        """
        now = time.time()
        with self._lock:
            if key not in self._cache:
                return None

            value, expires_at = self._cache[key]
            if self._is_expired(expires_at, now):
                del self._cache[key]
                return None

            self._cache.move_to_end(key)
            return value

    def delete(self, key: str) -> bool:
        """Deletes key from the cache.

        Returns True if the key existed (and was not expired) and was deleted,
        else False.
        """
        now = time.time()
        with self._lock:
            if key not in self._cache:
                return False

            _, expires_at = self._cache.pop(key)
            return not self._is_expired(expires_at, now)

    def cleanup_expired(self) -> int:
        """Removes all expired keys and returns the count of removed items."""
        now = time.time()
        with self._lock:
            expired_keys = [
                key
                for key, (_, expires_at) in self._cache.items()
                if self._is_expired(expires_at, now)
            ]
            for key in expired_keys:
                del self._cache[key]
            return len(expired_keys)

    def size(self) -> int:
        """Returns the number of currently valid (non-expired) items."""
        now = time.time()
        with self._lock:
            return sum(
                1
                for _, expires_at in self._cache.values()
                if not self._is_expired(expires_at, now)
            )

    def __len__(self) -> int:
        return self.size()

    def __contains__(self, key: str) -> bool:
        now = time.time()
        with self._lock:
            if key not in self._cache:
                return False
            _, expires_at = self._cache[key]
            if self._is_expired(expires_at, now):
                del self._cache[key]
                return False
            return True
