import bisect
import threading
import time
from collections import deque
from typing import Optional


class SlidingWindowRateLimiter:
    """Thread-safe sliding window log rate limiter."""

    def __init__(self, max_requests: int, window_seconds: float) -> None:
        if max_requests <= 0:
            raise ValueError("max_requests must be a positive integer")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be a positive number")

        self.max_requests: int = int(max_requests)
        self.window_seconds: float = float(window_seconds)
        self._requests: dict[str, deque[float]] = {}
        self._lock = threading.RLock()

    def _evict_expired(self, key: str, now: float) -> Optional[deque[float]]:
        timestamps = self._requests.get(key)
        if not timestamps:
            return None

        cutoff = now - self.window_seconds
        while timestamps and (timestamps[0] <= cutoff or now - timestamps[0] >= self.window_seconds):
            timestamps.popleft()

        if not timestamps:
            del self._requests[key]
            return None

        return timestamps

    def allow_request(
        self, key: str, timestamp: Optional[float] = None
    ) -> tuple[bool, float]:
        with self._lock:
            now = time.time() if timestamp is None else float(timestamp)
            timestamps = self._evict_expired(key, now)

            if timestamps is None:
                timestamps = deque()
                self._requests[key] = timestamps

            if len(timestamps) < self.max_requests:
                if not timestamps or now >= timestamps[-1]:
                    timestamps.append(now)
                else:
                    bisect.insort(timestamps, now)
                return True, 0.0

            oldest_relevant = timestamps[len(timestamps) - self.max_requests]
            retry_after = max(0.0, (oldest_relevant + self.window_seconds) - now)
            return False, float(retry_after)

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        with self._lock:
            now = time.time() if timestamp is None else float(timestamp)
            timestamps = self._evict_expired(key, now)
            used = len(timestamps) if timestamps is not None else 0
            return max(0, self.max_requests - used)
