from typing import Any


class QuorumCluster:
    """Coordinates distributed quorum consensus across a cluster of N nodes."""

    def __init__(self, node_ids: list[str]) -> None:
        self.node_ids: list[str] = list(dict.fromkeys(node_ids))
        self.n: int = len(self.node_ids)
        self.quorum_threshold: int = (self.n // 2) + 1

        # Per-node committed key-value store
        self._node_state: dict[str, dict[str, Any]] = {
            node_id: {} for node_id in self.node_ids
        }
        # Authoritative committed state across the cluster
        self._committed_state: dict[str, Any] = {}

        # Active network partitions; initially all nodes are in a single connected component
        self._partitions: list[set[str]] = [set(self.node_ids)]

    def _get_node_partition(self, node_id: str) -> set[str]:
        for part in self._partitions:
            if node_id in part:
                return part
        return set()

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        """Divides the cluster into isolated network partitions."""
        set_a = set(group_a) & set(self.node_ids)
        set_b = (set(group_b) & set(self.node_ids)) - set_a
        remaining = set(self.node_ids) - set_a - set_b

        new_partitions: list[set[str]] = []
        if set_a:
            new_partitions.append(set_a)
        if set_b:
            new_partitions.append(set_b)
        for node in remaining:
            new_partitions.append({node})

        self._partitions = new_partitions

    def heal_partition(self) -> None:
        """Restores full connectivity and synchronizes committed state across all nodes."""
        self._partitions = [set(self.node_ids)]
        for node_id in self.node_ids:
            self._node_state[node_id] = dict(self._committed_state)

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        """Proposes a write from `from_node`, committing only if in a strict majority partition."""
        if from_node not in self._node_state:
            return False

        active_partition = self._get_node_partition(from_node)
        if len(active_partition) < self.quorum_threshold:
            return False

        self._committed_state[key] = value
        for node_id in active_partition:
            self._node_state[node_id][key] = value

        return True

    def read_value(self, from_node: str, key: str) -> Any:
        """Returns the committed value for `key` on `from_node`, or `None` if not set."""
        if from_node not in self._node_state:
            return None
        return self._node_state[from_node].get(key, None)
