from threading import RLock
from typing import Dict, List


class ResilientConnectionPool:
    """A thread-safe, resilient database connection pool wrapper."""

    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0) -> None:
        if max_connections < 0:
            raise ValueError("max_connections must be non-negative")
        if ping_timeout <= 0:
            raise ValueError("ping_timeout must be positive")

        self.max_connections: int = max_connections
        self.ping_timeout: float = ping_timeout
        self._lock: RLock = RLock()
        self._next_id: int = 1
        self._pool: List[Dict[str, object]] = [
            self._create_connection() for _ in range(max_connections)
        ]
        self.pool = self._pool
        self.connections = self._pool
        self._in_use: List[Dict[str, object]] = []

    def _create_connection(self) -> dict:
        conn = {"id": self._next_id, "alive": True}
        self._next_id += 1
        return conn

    def acquire(self) -> dict:
        with self._lock:
            if not self._pool:
                raise RuntimeError("Pool exhausted")

            for idx, conn in enumerate(self._pool):
                if conn.get("alive", False):
                    active_conn = self._pool.pop(idx)
                    self._in_use.append(active_conn)
                    return active_conn

            # If only dead connections remain in the pool, replace one with a new alive connection
            self._pool.pop(0)
            active_conn = self._create_connection()
            self._in_use.append(active_conn)
            return active_conn

    def release(self, conn: dict) -> None:
        if not isinstance(conn, dict):
            raise TypeError("conn must be a dictionary")

        with self._lock:
            for idx, active_conn in enumerate(self._in_use):
                if active_conn is conn or active_conn.get("id") == conn.get("id"):
                    self._in_use.pop(idx)
                    break

            if any(existing is conn for existing in self._pool):
                return

            if len(self._pool) < self.max_connections:
                self._pool.append(conn)

    def health_check_and_heal(self) -> int:
        with self._lock:
            healed_count = 0
            for idx, conn in enumerate(self._pool):
                if conn.get("alive") is False or not conn.get("alive", False):
                    self._pool[idx] = self._create_connection()
                    healed_count += 1
            return healed_count

    def close_all(self) -> None:
        with self._lock:
            for conn in self._pool:
                conn["alive"] = False
            for conn in self._in_use:
                conn["alive"] = False
            self._pool.clear()
            self._in_use.clear()
