import ast


def prune_dead_code_and_imports(source_code: str) -> str:
    tree = ast.parse(source_code)

    def _collect_usage(nodes: list[ast.AST]) -> tuple[set[str], set[str], set[str]]:
        used_names: set[str] = set()
        used_dotted: set[str] = set()
        attr_bases: set[int] = set()

        def _get_dotted(node: ast.AST) -> str | None:
            if isinstance(node, ast.Name) and isinstance(node.ctx, (ast.Load, ast.Del)):
                return node.id
            if isinstance(node, ast.Attribute) and isinstance(
                node.ctx, (ast.Load, ast.Del)
            ):
                parent = _get_dotted(node.value)
                if parent:
                    return f"{parent}.{node.attr}"
            return None

        for root in nodes:
            for node in ast.walk(root):
                if isinstance(node, ast.Attribute) and isinstance(
                    node.ctx, (ast.Load, ast.Del)
                ):
                    attr_bases.add(id(node.value))
                dotted = _get_dotted(node)
                if dotted:
                    used_dotted.add(dotted)
                if isinstance(node, ast.Name) and isinstance(
                    node.ctx, (ast.Load, ast.Del)
                ):
                    used_names.add(node.id)
                elif isinstance(node, ast.AugAssign) and isinstance(
                    node.target, ast.Name
                ):
                    used_names.add(node.target.id)

        standalone_names: set[str] = set()
        for root in nodes:
            for node in ast.walk(root):
                if isinstance(node, ast.Name) and isinstance(
                    node.ctx, (ast.Load, ast.Del)
                ):
                    if id(node) not in attr_bases:
                        standalone_names.add(node.id)
                elif isinstance(node, ast.AugAssign) and isinstance(
                    node.target, ast.Name
                ):
                    standalone_names.add(node.target.id)

        return used_names, used_dotted, standalone_names

    private_funcs = [
        stmt
        for stmt in tree.body
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef))
        and stmt.name.startswith("_")
    ]
    live_stmts = [
        stmt
        for stmt in tree.body
        if not (
            isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef))
            and stmt.name.startswith("_")
        )
    ]

    live_set = {id(stmt) for stmt in live_stmts}
    used_names, _, _ = _collect_usage(live_stmts)

    changed = True
    while changed:
        changed = False
        for fn in private_funcs:
            if id(fn) not in live_set and fn.name in used_names:
                live_set.add(id(fn))
                live_stmts.append(fn)
                fn_names, _, _ = _collect_usage([fn])
                used_names |= fn_names
                changed = True

    tree.body = [stmt for stmt in tree.body if id(stmt) in live_set]

    used_names, used_dotted, standalone_names = _collect_usage(tree.body)

    class _ImportPruner(ast.NodeTransformer):
        def generic_visit(self, node: ast.AST) -> ast.AST:
            node = super().generic_visit(node)
            if not isinstance(node, ast.Module) and hasattr(node, "body"):
                body = getattr(node, "body")
                if isinstance(body, list) and len(body) == 0:
                    setattr(node, "body", [ast.Pass()])
            return node

        def visit_Import(self, node: ast.Import) -> ast.Import | None:
            kept = []
            for alias in node.names:
                if alias.asname:
                    if alias.asname in used_names:
                        kept.append(alias)
                elif "." in alias.name:
                    root_name = alias.name.split(".")[0]
                    if alias.name in used_dotted or root_name in standalone_names:
                        kept.append(alias)
                else:
                    if alias.name in used_names:
                        kept.append(alias)
            if not kept:
                return None
            node.names = kept
            return node

        def visit_ImportFrom(self, node: ast.ImportFrom) -> ast.ImportFrom | None:
            if node.module == "__future__":
                return node
            kept = []
            for alias in node.names:
                if alias.name == "*":
                    kept.append(alias)
                else:
                    bound_name = alias.asname if alias.asname else alias.name
                    if bound_name in used_names:
                        kept.append(alias)
            if not kept:
                return None
            node.names = kept
            return node

    tree = _ImportPruner().visit(tree)
    ast.fix_missing_locations(tree)
    refactored_code = ast.unparse(tree)
    compile(refactored_code, "<string>", "exec")
    return refactored_code
