import ntpath
import os
import posixpath
import shutil
import stat
import unicodedata
import zipfile
import zlib


class _InvalidArchiveError(ValueError, zipfile.BadZipFile):
    """Exception matching both ValueError and zipfile.BadZipFile."""


def _is_symlink_or_special(info: zipfile.ZipInfo) -> bool:
    unix_mode = (info.external_attr >> 16) & 0xFFFF
    low_mode = info.external_attr & 0xFFFF
    if stat.S_ISLNK(unix_mode) or stat.S_ISLNK(low_mode):
        return True
    file_type = stat.S_IFMT(unix_mode)
    if file_type not in (0, stat.S_IFREG, stat.S_IFDIR):
        return True
    return False


def _is_directory_entry(info: zipfile.ZipInfo, raw_name: str) -> bool:
    unix_mode = (info.external_attr >> 16) & 0xFFFF
    return (
        info.is_dir()
        or raw_name.endswith(("/", "\\"))
        or stat.S_ISDIR(unix_mode)
    )


def _normalize_and_validate_path(raw_name: str, is_dir: bool) -> tuple[str, ...]:
    if not raw_name or "\x00" in raw_name:
        raise ValueError(f"Invalid archive entry name: {raw_name!r}")

    for candidate in (raw_name, unicodedata.normalize("NFC", raw_name)):
        if (
            candidate.startswith(("/", "\\"))
            or posixpath.isabs(candidate)
            or ntpath.isabs(candidate)
            or bool(ntpath.splitdrive(candidate)[0])
        ):
            raise ValueError(f"Absolute path not allowed: {raw_name!r}")

    nfc_name = unicodedata.normalize("NFC", raw_name)
    unified = nfc_name.replace("\\", "/")
    if is_dir:
        unified = unified.rstrip("/")
        if not unified:
            raise ValueError(f"Invalid directory entry name: {raw_name!r}")

    raw_parts = unified.split("/")
    if any(part in ("", ".", "..") for part in raw_parts):
        raise ValueError(f"Invalid or traversal path segment in: {raw_name!r}")

    parts = tuple(unicodedata.normalize("NFC", part) for part in raw_parts)
    if any(
        "\x00" in part or part in ("", ".", "..") or bool(ntpath.splitdrive(part)[0])
        for part in parts
    ):
        raise ValueError(f"Invalid normalized path segment in: {raw_name!r}")

    return parts


def _validate_destination_target(
    dest_root: str, parts: tuple[str, ...], is_dir: bool
) -> None:
    if os.path.exists(dest_root):
        if os.path.islink(dest_root) or not os.path.isdir(dest_root):
            raise ValueError("Destination path must be a non-symlink directory")

    dest_real = os.path.realpath(dest_root)
    candidate = os.path.abspath(os.path.join(dest_real, *parts))
    if os.path.commonpath([dest_real, candidate]) != dest_real or candidate == dest_real:
        raise ValueError(f"Entry escapes destination: {'/'.join(parts)!r}")

    current = dest_root
    for idx, part in enumerate(parts):
        current = os.path.join(current, part)
        is_last = idx == len(parts) - 1
        if os.path.lexists(current):
            if os.path.islink(current):
                raise ValueError(f"Destination contains symlink at: {current!r}")
            if not is_last:
                if not os.path.isdir(current):
                    raise ValueError(
                        f"Destination contains non-directory parent at: {current!r}"
                    )
            elif is_dir:
                if not os.path.isdir(current):
                    raise ValueError(
                        f"Destination contains file where directory is expected: {current!r}"
                    )
            else:
                if os.path.isdir(current):
                    raise ValueError(
                        f"Destination contains directory where file is expected: {current!r}"
                    )


def safe_extract_zip(
    archive_path: str,
    destination: str,
    max_files: int = 1000,
    max_uncompressed_bytes: int = 10000000,
    max_compression_ratio: float = 100.0,
) -> list[str]:
    if max_files < 0:
        raise ValueError("max_files must be non-negative")
    if max_uncompressed_bytes < 0:
        raise ValueError("max_uncompressed_bytes must be non-negative")
    if max_compression_ratio <= 0:
        raise ValueError("max_compression_ratio must be positive")

    archive_fs = os.fspath(archive_path)
    dest_fs = os.path.abspath(os.fspath(destination))

    try:
        with zipfile.ZipFile(archive_fs, "r") as zf:
            infos = zf.infolist()

            seen_files: set[str] = set()
            seen_explicit_dirs: set[str] = set()
            seen_implicit_dirs: set[str] = set()

            validated_dirs: list[tuple[str, ...]] = []
            validated_files: list[tuple[zipfile.ZipInfo, tuple[str, ...], str]] = []

            file_count = 0
            declared_total_bytes = 0

            for info in infos:
                raw_name = info.filename
                if _is_symlink_or_special(info):
                    raise ValueError(f"Unsupported or symlink entry: {raw_name!r}")

                is_dir = _is_directory_entry(info, raw_name)
                parts = _normalize_and_validate_path(raw_name, is_dir)
                norm_posix = "/".join(parts)

                for depth in range(1, len(parts)):
                    parent_posix = "/".join(parts[:depth])
                    if parent_posix in seen_files:
                        raise ValueError(
                            f"Path collision between file and directory: {parent_posix!r}"
                        )
                    seen_implicit_dirs.add(parent_posix)

                _validate_destination_target(dest_fs, parts, is_dir)

                if is_dir:
                    if info.file_size != 0:
                        raise ValueError(
                            f"Directory entry has non-zero size: {raw_name!r}"
                        )
                    if norm_posix in seen_files or norm_posix in seen_explicit_dirs:
                        raise ValueError(
                            f"Duplicate or colliding directory entry: {norm_posix!r}"
                        )
                    seen_explicit_dirs.add(norm_posix)
                    seen_implicit_dirs.add(norm_posix)
                    validated_dirs.append(parts)
                else:
                    if (
                        norm_posix in seen_files
                        or norm_posix in seen_explicit_dirs
                        or norm_posix in seen_implicit_dirs
                    ):
                        raise ValueError(
                            f"Colliding archive entry after NFC normalization: {norm_posix!r}"
                        )
                    seen_files.add(norm_posix)

                    file_count += 1
                    if file_count > max_files:
                        raise ValueError("Archive exceeds max_files limit")

                    if info.file_size < 0 or info.compress_size < 0:
                        raise ValueError(f"Negative size in archive entry: {raw_name!r}")

                    if info.file_size > 0:
                        if info.compress_size == 0:
                            raise ValueError(
                                f"Zero compressed size for non-empty entry: {raw_name!r}"
                            )
                        if (info.file_size / info.compress_size) > max_compression_ratio:
                            raise ValueError(
                                f"Entry exceeds max_compression_ratio: {raw_name!r}"
                            )

                    declared_total_bytes += info.file_size
                    if declared_total_bytes > max_uncompressed_bytes:
                        raise ValueError(
                            "Archive exceeds max_uncompressed_bytes limit"
                        )

                    validated_files.append((info, parts, norm_posix))

            actual_total_bytes = 0
            for info in infos:
                raw_name = info.filename
                is_dir = _is_directory_entry(info, raw_name)
                entry_bytes = 0
                with zf.open(info, "r") as src:
                    while True:
                        chunk = src.read(65536)
                        if not chunk:
                            break
                        entry_bytes += len(chunk)
                        if is_dir:
                            raise ValueError(
                                f"Directory entry contains payload data: {raw_name!r}"
                            )
                        actual_total_bytes += len(chunk)
                        if actual_total_bytes > max_uncompressed_bytes:
                            raise ValueError(
                                "Archive stream exceeds max_uncompressed_bytes limit"
                            )
                        if (
                            info.compress_size == 0
                            or (entry_bytes / info.compress_size) > max_compression_ratio
                        ):
                            raise ValueError(
                                f"Archive stream exceeds max_compression_ratio: {raw_name!r}"
                            )
                if entry_bytes != info.file_size:
                    raise ValueError(
                        f"Archive entry size mismatch for {raw_name!r}: "
                        f"expected {info.file_size}, got {entry_bytes}"
                    )

            os.makedirs(dest_fs, exist_ok=True)

            for dir_parts in validated_dirs:
                target_dir = os.path.join(dest_fs, *dir_parts)
                os.makedirs(target_dir, exist_ok=True)

            extracted_paths: list[str] = []
            for info, file_parts, norm_posix in validated_files:
                target_file = os.path.join(dest_fs, *file_parts)
                parent_dir = os.path.dirname(target_file)
                os.makedirs(parent_dir, exist_ok=True)
                with zf.open(info, "r") as src, open(target_file, "wb") as dst:
                    shutil.copyfileobj(src, dst, length=65536)
                extracted_paths.append(norm_posix)

            extracted_paths.sort()
            return extracted_paths

    except (zipfile.BadZipFile, zlib.error, EOFError, RuntimeError) as exc:
        if isinstance(exc, ValueError):
            raise
        raise _InvalidArchiveError(f"Invalid or corrupt zip archive: {exc}") from exc
