from collections.abc import Mapping
from dataclasses import dataclass, field
from decimal import Decimal
import re

_REQUIRED_EVENT_FIELDS = frozenset(
    {"event_id", "payment_id", "sequence", "type", "amount"}
)
_SUPPORTED_EVENT_TYPES = frozenset(
    {"authorized", "captured", "refunded", "reversed"}
)
_AMOUNT_PATTERN = re.compile(r"\d+(?:\.\d{1,2})?", re.ASCII)
_ZERO = Decimal("0.00")
_TWO_PLACES = Decimal("0.01")


def _format_decimal(value: Decimal) -> str:
    return str(value.quantize(_TWO_PLACES))


@dataclass(frozen=True)
class _EventRecord:
    event_id: str
    payment_id: str
    sequence: int
    event_type: str
    amount: Decimal


@dataclass
class _PaymentRecord:
    authorized: Decimal = _ZERO
    captured: Decimal = _ZERO
    refunded: Decimal = _ZERO
    reversed: Decimal = _ZERO
    next_sequence: int = 1
    applied: dict[int, _EventRecord] = field(default_factory=dict)
    buffered: dict[int, _EventRecord] = field(default_factory=dict)

    def to_state_dict(self) -> dict[str, str | int]:
        available_to_capture = self.authorized - self.captured
        merchant_balance = self.captured - self.refunded - self.reversed
        return {
            "authorized": _format_decimal(self.authorized),
            "captured": _format_decimal(self.captured),
            "refunded": _format_decimal(self.refunded),
            "reversed": _format_decimal(self.reversed),
            "available_to_capture": _format_decimal(available_to_capture),
            "merchant_balance": _format_decimal(merchant_balance),
            "next_sequence": int(self.next_sequence),
        }


class PaymentLedger:
    """Stateful payment ledger supporting out-of-order buffering and atomic draining."""

    def __init__(self) -> None:
        self._payments: dict[str, _PaymentRecord] = {}
        self._events_by_id: dict[str, _EventRecord] = {}

    @staticmethod
    def _parse_and_validate_event(event: dict) -> _EventRecord:
        if not isinstance(event, Mapping):
            raise ValueError("Event must be a mapping.")
        if set(event.keys()) != _REQUIRED_EVENT_FIELDS:
            raise ValueError("Event must contain exact required fields.")

        event_id = event["event_id"]
        if not isinstance(event_id, str) or not event_id.strip():
            raise ValueError("event_id must be a non-empty string.")

        payment_id = event["payment_id"]
        if not isinstance(payment_id, str) or not payment_id.strip():
            raise ValueError("payment_id must be a non-empty string.")

        sequence = event["sequence"]
        if (
            not isinstance(sequence, int)
            or isinstance(sequence, bool)
            or sequence < 1
        ):
            raise ValueError("sequence must be a positive integer.")

        event_type = event["type"]
        if (
            not isinstance(event_type, str)
            or event_type not in _SUPPORTED_EVENT_TYPES
        ):
            raise ValueError("Unsupported event type.")

        raw_amount = event["amount"]
        if not isinstance(raw_amount, str) or not _AMOUNT_PATTERN.fullmatch(
            raw_amount
        ):
            raise ValueError(
                "amount must be a positive decimal string with at most two fractional digits."
            )

        amount = Decimal(raw_amount).quantize(_TWO_PLACES)
        if amount <= _ZERO:
            raise ValueError("amount must be positive.")

        return _EventRecord(
            event_id=event_id,
            payment_id=payment_id,
            sequence=sequence,
            event_type=event_type,
            amount=amount,
        )

    @staticmethod
    def _apply_single_transition(
        authorized: Decimal,
        captured: Decimal,
        refunded: Decimal,
        reversed_amt: Decimal,
        record: _EventRecord,
    ) -> tuple[Decimal, Decimal, Decimal, Decimal]:
        if record.sequence == 1:
            if record.event_type != "authorized":
                raise ValueError("Sequence 1 must authorize.")
            return (
                authorized + record.amount,
                captured,
                refunded,
                reversed_amt,
            )

        if record.event_type == "authorized":
            raise ValueError("Only sequence 1 may authorize.")

        if record.event_type == "captured":
            if captured + record.amount > authorized:
                raise ValueError("Capture cannot exceed authorization.")
            return (
                authorized,
                captured + record.amount,
                refunded,
                reversed_amt,
            )

        remaining_settled = captured - refunded - reversed_amt
        if record.event_type == "refunded":
            if record.amount > remaining_settled:
                raise ValueError("Refund cannot exceed remaining settled amount.")
            return (
                authorized,
                captured,
                refunded + record.amount,
                reversed_amt,
            )

        if record.event_type == "reversed":
            if record.amount > remaining_settled:
                raise ValueError("Reversal cannot exceed remaining settled amount.")
            return (
                authorized,
                captured,
                refunded,
                reversed_amt + record.amount,
            )

        raise ValueError("Unsupported event type.")

    def apply(self, event: dict) -> str:
        record = self._parse_and_validate_event(event)

        existing_by_id = self._events_by_id.get(record.event_id)
        if existing_by_id is not None:
            if existing_by_id == record:
                return "duplicate"
            raise ValueError("Event ID reused with different content.")

        payment = self._payments.get(record.payment_id)
        if payment is not None:
            if (
                record.sequence in payment.applied
                or record.sequence in payment.buffered
            ):
                raise ValueError("Sequence reused with different content.")

        if (record.sequence == 1) != (record.event_type == "authorized"):
            raise ValueError("Sequence 1 must authorize and subsequent sequences cannot authorize.")

        next_seq = 1 if payment is None else payment.next_sequence

        if record.sequence < next_seq:
            raise ValueError("Sequence already processed.")

        if record.sequence > next_seq:
            if payment is None:
                payment = _PaymentRecord()
                self._payments[record.payment_id] = payment
            payment.buffered[record.sequence] = record
            self._events_by_id[record.event_id] = record
            return "buffered"

        # record.sequence == next_seq: simulate atomic drain before mutating state
        authorized = _ZERO if payment is None else payment.authorized
        captured = _ZERO if payment is None else payment.captured
        refunded = _ZERO if payment is None else payment.refunded
        reversed_amt = _ZERO if payment is None else payment.reversed

        to_apply: list[_EventRecord] = [record]
        sim_seq = next_seq + 1
        if payment is not None:
            while sim_seq in payment.buffered:
                to_apply.append(payment.buffered[sim_seq])
                sim_seq += 1

        for ev in to_apply:
            authorized, captured, refunded, reversed_amt = (
                self._apply_single_transition(
                    authorized, captured, refunded, reversed_amt, ev
                )
            )

        if payment is None:
            payment = _PaymentRecord()
            self._payments[record.payment_id] = payment

        payment.authorized = authorized
        payment.captured = captured
        payment.refunded = refunded
        payment.reversed = reversed_amt
        payment.next_sequence = sim_seq

        self._events_by_id[record.event_id] = record
        for ev in to_apply:
            payment.buffered.pop(ev.sequence, None)
            payment.applied[ev.sequence] = ev

        return "applied"

    def state(self, payment_id: str) -> dict | None:
        if not isinstance(payment_id, str):
            return None
        payment = self._payments.get(payment_id)
        if payment is None:
            return None
        return payment.to_state_dict()

    def snapshot(self) -> dict:
        return {
            payment_id: self._payments[payment_id].to_state_dict()
            for payment_id in sorted(self._payments.keys())
        }
