from typing import Any, Callable


class RetryableError(Exception):
    """Raised when a step fails transiently and can be retried."""


class FatalError(Exception):
    """Raised when a step fails permanently and triggers compensation."""


class CrashError(Exception):
    """Raised when execution crashes abruptly and must halt immediately."""


class _ValidationError(ValueError, TypeError):
    """Raised when input validation fails."""


class SagaOrchestrator:
    def __init__(
        self,
        executor: Callable[[str], Any],
        compensator: Callable[[str], Any],
        max_retries: int = 2,
        journal: dict | None = None,
    ) -> None:
        if not callable(executor):
            raise _ValidationError("executor must be callable")
        if not callable(compensator):
            raise _ValidationError("compensator must be callable")
        if isinstance(max_retries, bool) or not isinstance(max_retries, int) or max_retries < 0:
            raise _ValidationError("max_retries must be a non-negative integer")
        if journal is not None and not isinstance(journal, dict):
            raise _ValidationError("journal must be a dict or None")

        self.executor = executor
        self.compensator = compensator
        self.max_retries = max_retries
        self.journal: dict[str, dict[str, Any]] = {} if journal is None else journal

    def _validate(self, saga_id: str, steps: list[str]) -> list[str]:
        if not isinstance(saga_id, str):
            raise _ValidationError("saga_id must be a string")
        if not saga_id or not saga_id.strip():
            raise ValueError("saga_id must be a non-empty string")

        if not isinstance(steps, (list, tuple)):
            raise _ValidationError("steps must be a list of unique non-empty strings")
        if not steps:
            raise ValueError("steps must not be empty")

        normalized_steps: list[str] = []
        seen: set[str] = set()
        for step in steps:
            if not isinstance(step, str):
                raise _ValidationError("Each step must be a string")
            if not step or not step.strip():
                raise ValueError("Steps must be non-empty strings")
            if step in seen:
                raise ValueError(f"Duplicate step name: {step!r}")
            seen.add(step)
            normalized_steps.append(step)

        if saga_id in self.journal:
            existing = self.journal[saga_id]
            if not isinstance(existing, dict) or "steps" not in existing:
                raise ValueError(f"Corrupted journal state for saga {saga_id!r}")
            if list(existing["steps"]) != normalized_steps:
                raise ValueError(f"Step plan changed for existing saga {saga_id!r}")

        return normalized_steps

    def _ensure_entry(self, saga_id: str, steps: list[str]) -> dict[str, Any]:
        if saga_id not in self.journal:
            self.journal[saga_id] = {
                "steps": list(steps),
                "status": "running",
                "state": "running",
                "compensating": False,
                "completed": [],
                "completed_steps": [],
                "compensated": [],
                "compensated_steps": [],
            }
        return self.journal[saga_id]

    @staticmethod
    def _set_status(entry: dict[str, Any], status: str) -> None:
        entry["status"] = status
        entry["state"] = status
        entry["compensating"] = status == "compensating"

    @staticmethod
    def _record_completed(entry: dict[str, Any], step: str) -> None:
        if step not in entry["completed_steps"]:
            entry["completed_steps"].append(step)
        if entry.get("completed") is not entry["completed_steps"]:
            if step not in entry.setdefault("completed", []):
                entry["completed"].append(step)

    @staticmethod
    def _record_compensated(entry: dict[str, Any], step: str) -> None:
        if step not in entry["compensated_steps"]:
            entry["compensated_steps"].append(step)
        if entry.get("compensated") is not entry["compensated_steps"]:
            if step not in entry.setdefault("compensated", []):
                entry["compensated"].append(step)

    def _compensate(self, entry: dict[str, Any]) -> str:
        self._set_status(entry, "compensating")
        completed_steps = list(entry.get("completed_steps", entry.get("completed", [])))
        compensated_steps = set(entry.get("compensated_steps", entry.get("compensated", [])))

        for step in reversed(completed_steps):
            if step in compensated_steps:
                continue

            attempt = 0
            while True:
                try:
                    self.compensator(step)
                    break
                except CrashError:
                    raise
                except RetryableError:
                    if attempt < self.max_retries:
                        attempt += 1
                        continue
                    raise FatalError(f"Compensation retries exhausted for step {step!r}")
                except FatalError:
                    raise
                except Exception as exc:
                    raise FatalError(f"Fatal error during compensation of step {step!r}") from exc

            self._record_compensated(entry, step)
            compensated_steps.add(step)

        self._set_status(entry, "compensated")
        return "compensated"

    def _execute(self, saga_id: str, steps: list[str]) -> str:
        normalized_steps = self._validate(saga_id, steps)
        entry = self._ensure_entry(saga_id, normalized_steps)

        status = entry.get("status", entry.get("state", "running"))
        if status == "completed":
            return "completed"
        if status == "compensated":
            return "compensated"
        if status == "compensating" or entry.get("compensating") is True:
            return self._compensate(entry)

        completed_steps = set(entry.get("completed_steps", entry.get("completed", [])))

        for step in normalized_steps:
            if step in completed_steps:
                continue

            attempt = 0
            while True:
                try:
                    self.executor(step)
                    break
                except CrashError:
                    raise
                except RetryableError:
                    if attempt < self.max_retries:
                        attempt += 1
                        continue
                    self._set_status(entry, "compensating")
                    return self._compensate(entry)
                except FatalError:
                    self._set_status(entry, "compensating")
                    return self._compensate(entry)
                except Exception:
                    self._set_status(entry, "compensating")
                    return self._compensate(entry)

            self._record_completed(entry, step)
            completed_steps.add(step)

        self._set_status(entry, "completed")
        return "completed"

    def run(self, saga_id: str, steps: list[str]) -> str:
        return self._execute(saga_id, steps)

    def recover(self, saga_id: str, steps: list[str]) -> str:
        return self._execute(saga_id, steps)
