import bisect
import collections
import threading
import time
from typing import Optional


class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: float) -> None:
        self.max_requests = max_requests
        self.window_seconds = float(window_seconds)
        self._lock = threading.Lock()
        self._windows: dict[str, collections.deque[float]] = {}

    def _prune(self, window: collections.deque[float], cutoff: float) -> None:
        while window and window[0] <= cutoff:
            window.popleft()

    def allow_request(
        self, key: str, timestamp: Optional[float] = None
    ) -> tuple[bool, float]:
        with self._lock:
            now = time.time() if timestamp is None else float(timestamp)

            if self.max_requests <= 0:
                return (False, float(self.window_seconds))

            cutoff = now - self.window_seconds
            window = self._windows.get(key)
            if window is None:
                window = collections.deque()
                self._windows[key] = window
            else:
                self._prune(window, cutoff)

            if len(window) < self.max_requests:
                if not window or now >= window[-1]:
                    window.append(now)
                else:
                    bisect.insort(window, now)
                return (True, 0.0)
            else:
                oldest_index = len(window) - self.max_requests
                oldest_relevant_ts = window[oldest_index]
                retry_after = max(0.0, (oldest_relevant_ts + self.window_seconds) - now)
                return (False, float(retry_after))

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        with self._lock:
            now = time.time() if timestamp is None else float(timestamp)

            if self.max_requests <= 0:
                return 0

            cutoff = now - self.window_seconds
            window = self._windows.get(key)
            if window is None:
                return max(0, self.max_requests)

            self._prune(window, cutoff)
            if not window:
                self._windows.pop(key, None)
                return max(0, self.max_requests)

            return max(0, self.max_requests - len(window))
