import asyncio
import inspect
from typing import Any, Callable, Coroutine, Optional, Set


class AsyncWorkerPool:
    """An asynchronous worker pool using standard asyncio with priority-based

    queueing, concurrency control, and graceful/immediate shutdown capabilities.
    """

    def __init__(self, concurrency: int = 3, max_queue_size: int = 100) -> None:
        if concurrency <= 0:
            raise ValueError("concurrency must be greater than 0")
        if max_queue_size < 0:
            raise ValueError("max_queue_size must be non-negative")

        self.concurrency: int = concurrency
        self.max_queue_size: int = max_queue_size

        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(
            maxsize=max_queue_size
        )
        self._workers: list[asyncio.Task] = []
        self._active_tasks: Set[asyncio.Task] = set()

        self._counter: int = 0
        self._is_started: bool = False
        self._is_shutting_down: bool = False
        self._shutdown_event: asyncio.Event = asyncio.Event()
        self._shutdown_complete: asyncio.Event = asyncio.Event()

    async def start(self) -> None:
        """Spawns worker tasks."""
        if self._is_shutting_down:
            raise RuntimeError("Pool is shutting down")
        if self._is_started:
            return

        self._is_started = True
        loop = asyncio.get_running_loop()
        self._workers = [
            loop.create_task(
                self._worker_loop(), name=f"AsyncWorkerPool-Worker-{i}"
            )
            for i in range(self.concurrency)
        ]

    async def submit(
        self,
        coro_func: Any,
        *args: Any,
        priority: int = 0,
        **kwargs: Any,
    ) -> asyncio.Future:
        """Enqueues a coroutine function coro_func(*args, **kwargs) to be executed by the pool workers.

        - Higher priority integer executes before lower priority integers.
        - Returns an asyncio.Future that resolves with the result (or exception)
        of coro_func(*args, **kwargs).
        - If pool is shutting down, raises RuntimeError("Pool is shutting down").
        """
        if self._is_shutting_down:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        future: asyncio.Future = loop.create_future()

        # Negate priority because asyncio.PriorityQueue is a min-heap.
        # self._counter serves as a tie-breaker for identical priorities (FIFO)
        # and avoids comparing unorderable callables or futures.
        item = (-priority, self._counter, coro_func, args, kwargs, future)
        self._counter += 1

        # Attempt non-blocking enqueue first
        try:
            self._queue.put_nowait(item)
            return future
        except asyncio.QueueFull:
            pass

        # If queue is full, wait for space while actively monitoring shutdown
        put_task = asyncio.create_task(self._queue.put(item))
        shutdown_waiter = asyncio.create_task(self._shutdown_event.wait())

        try:
            done, pending = await asyncio.wait(
                [put_task, shutdown_waiter],
                return_when=asyncio.FIRST_COMPLETED,
            )
        except asyncio.CancelledError:
            put_task.cancel()
            shutdown_waiter.cancel()
            await asyncio.gather(
                put_task, shutdown_waiter, return_exceptions=True
            )
            if not future.done():
                future.cancel()
            raise

        for t in pending:
            t.cancel()
        await asyncio.gather(*pending, return_exceptions=True)

        if self._shutdown_event.is_set():
            if not future.done():
                future.cancel()
            raise RuntimeError("Pool is shutting down")

        return future

    async def _worker_loop(self) -> None:
        """Internal worker loop consuming tasks from the priority queue."""
        while True:
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                break

            try:
                sort_priority, count, coro_func, args, kwargs, future = item

                # If the future was cancelled while queued, skip execution
                if future.cancelled():
                    continue

                job_task = asyncio.create_task(
                    self._execute_job(future, coro_func, args, kwargs)
                )
                self._active_tasks.add(job_task)

                # Propagate future cancellation to the running job task
                def on_future_done(f: asyncio.Future) -> None:
                    if f.cancelled() and not job_task.done():
                        job_task.cancel()

                future.add_done_callback(on_future_done)

                try:
                    await asyncio.shield(job_task)
                except asyncio.CancelledError:
                    job_task.cancel()
                    try:
                        await job_task
                    except asyncio.CancelledError:
                        pass
                    raise
                finally:
                    self._active_tasks.discard(job_task)
            finally:
                self._queue.task_done()

    async def _execute_job(
        self,
        future: asyncio.Future,
        coro_func: Any,
        args: tuple,
        kwargs: dict,
    ) -> None:
        """Executes a single job and resolves its future."""
        try:
            if future.cancelled():
                return

            if asyncio.iscoroutine(coro_func):
                res = await coro_func
            elif callable(coro_func):
                res = coro_func(*args, **kwargs)
                if inspect.isawaitable(res):
                    res = await res
            else:
                raise TypeError(
                    f"'{type(coro_func).__name__}' object is not callable or"
                    " awaitable"
                )

            if not future.done():
                future.set_result(res)
        except asyncio.CancelledError:
            if not future.done():
                future.cancel()
        except BaseException as exc:
            if not future.done():
                future.set_exception(exc)

    async def shutdown(
        self, drain: bool = True, timeout: Optional[float] = 5.0
    ) -> None:
        """Shuts down the worker pool.

        - If drain=True, waits for all currently enqueued tasks to complete before stopping workers.
        - If drain=False, cancels all queued and currently executing tasks immediately.
        - Respects optional timeout seconds.
        """
        if self._is_shutting_down:
            await self._shutdown_complete.wait()
            return

        self._is_shutting_down = True
        self._shutdown_event.set()

        try:
            if drain:
                # If workers were not started yet, start them to allow draining enqueued items
                if not self._is_started and not self._queue.empty():
                    await self.start()

                # Wait for queue to drain within the optional timeout
                try:
                    if timeout is not None:
                        await asyncio.wait_for(
                            self._queue.join(), timeout=timeout
                        )
                    else:
                        await self._queue.join()
                except (asyncio.TimeoutError, TimeoutError):
                    # Deadline reached while draining: force-cancel remaining tasks
                    self._cancel_queued_items()
                    for task in list(self._active_tasks):
                        task.cancel()
            else:
                # Immediate cancellation of all queued and currently executing tasks
                self._cancel_queued_items()
                for task in list(self._active_tasks):
                    task.cancel()

            # Stop worker loops
            for worker in self._workers:
                worker.cancel()

            # Wait for all workers and active tasks to terminate
            to_wait = list(self._workers) + list(self._active_tasks)
            if to_wait:
                gather_all = asyncio.gather(*to_wait, return_exceptions=True)
                if timeout is not None and not drain:
                    try:
                        await asyncio.wait_for(gather_all, timeout=timeout)
                    except (asyncio.TimeoutError, TimeoutError):
                        pass
                else:
                    await gather_all

        finally:
            self._workers.clear()
            self._active_tasks.clear()
            self._shutdown_complete.set()

    def _cancel_queued_items(self) -> None:
        """Cancels all remaining items in the queue and marks them task_done."""
        while not self._queue.empty():
            try:
                sort_priority, count, coro_func, args, kwargs, future = (
                    self._queue.get_nowait()
                )
                if not future.done():
                    future.cancel()
                self._queue.task_done()
            except asyncio.QueueEmpty:
                break

    async def __aenter__(self) -> "AsyncWorkerPool":
        await self.start()
        return self

    async def __aexit__(self, exc_type: Any, exc_val: Any, exc_tb: Any) -> None:
        await self.shutdown(drain=True)
