import fnmatch


def authorize(request: dict, policies: list[dict]) -> bool:
    if not isinstance(request, dict):
        return False

    required_request_keys = (
        "subject_id",
        "tenant_id",
        "resource_tenant_id",
        "roles",
        "action",
        "resource",
        "context",
    )
    for key in required_request_keys:
        if key not in request:
            return False

    for str_key in (
        "subject_id",
        "tenant_id",
        "resource_tenant_id",
        "action",
        "resource",
    ):
        val = request[str_key]
        if not isinstance(val, str) or len(val) == 0:
            return False

    req_roles = request["roles"]
    if not isinstance(req_roles, list) or len(req_roles) == 0:
        return False
    if not all(isinstance(r, str) and len(r) > 0 for r in req_roles):
        return False

    if not isinstance(request["context"], dict):
        return False

    if request["tenant_id"] != request["resource_tenant_id"]:
        return False

    if not isinstance(policies, list):
        return False

    required_policy_keys = ("effect", "tenant", "roles", "actions", "resources")
    for policy in policies:
        if not isinstance(policy, dict):
            return False

        for key in required_policy_keys:
            if key not in policy:
                return False

        if policy["effect"] not in ("allow", "deny"):
            return False

        tenant = policy["tenant"]
        if not isinstance(tenant, str) or len(tenant) == 0:
            return False

        for list_key in ("roles", "actions", "resources"):
            lst = policy[list_key]
            if not isinstance(lst, list) or len(lst) == 0:
                return False
            if not all(isinstance(item, str) and len(item) > 0 for item in lst):
                return False

        if "conditions" in policy:
            conditions = policy["conditions"]
            if not isinstance(conditions, dict):
                return False
            if not all(isinstance(k, str) for k in conditions):
                return False

    def condition_matches(ctx_val, cond_val) -> bool:
        if isinstance(cond_val, list):
            if ctx_val == cond_val:
                return True
            for item in cond_val:
                if isinstance(ctx_val, bool) != isinstance(item, bool):
                    continue
                if ctx_val == item:
                    return True
            return False
        else:
            if isinstance(ctx_val, bool) != isinstance(cond_val, bool):
                return False
            return ctx_val == cond_val

    def policy_matches(req: dict, pol: dict) -> bool:
        if pol["tenant"] != "*" and pol["tenant"] != req["tenant_id"]:
            return False

        pol_roles = pol["roles"]
        r_roles = req["roles"]
        if not (
            "*" in pol_roles
            or "*" in r_roles
            or bool(set(pol_roles) & set(r_roles))
        ):
            return False

        if not any(
            fnmatch.fnmatchcase(req["action"], pat) for pat in pol["actions"]
        ):
            return False

        if not any(
            fnmatch.fnmatchcase(req["resource"], pat)
            for pat in pol["resources"]
        ):
            return False

        if "conditions" in pol:
            ctx = req["context"]
            for cond_key, cond_val in pol["conditions"].items():
                if cond_key not in ctx:
                    return False
                if not condition_matches(ctx[cond_key], cond_val):
                    return False

        return True

    has_allow = False
    for policy in policies:
        if policy_matches(request, policy):
            if policy["effect"] == "deny":
                return False
            elif policy["effect"] == "allow":
                has_allow = True

    return has_allow
