import re
from decimal import Decimal, InvalidOperation


class PaymentLedger:
    _REQUIRED_FIELDS = frozenset({"event_id", "payment_id", "sequence", "type", "amount"})
    _VALID_TYPES = frozenset({"authorized", "captured", "refunded", "reversed"})
    _AMOUNT_RE = re.compile(r"^\d+(\.\d{1,2})?$")
    _TWO_PLACES = Decimal("0.01")
    _ZERO = Decimal("0")

    def __init__(self):
        self._payments = {}
        self._buffered = {}
        self._events_by_id = {}

    def apply(self, event: dict) -> str:
        if not isinstance(event, dict):
            raise ValueError("Event must be a dictionary")

        if set(event.keys()) != self._REQUIRED_FIELDS:
            raise ValueError("Event must have exactly the required fields")

        event_id = event["event_id"]
        if not isinstance(event_id, str) or not event_id.strip():
            raise ValueError("event_id must be a non-empty string")

        payment_id = event["payment_id"]
        if not isinstance(payment_id, str) or not payment_id.strip():
            raise ValueError("payment_id must be a non-empty string")

        sequence = event["sequence"]
        if type(sequence) is not int or sequence <= 0:
            raise ValueError("sequence must be a positive integer")

        event_type = event["type"]
        if event_type not in self._VALID_TYPES:
            raise ValueError("unsupported event type")

        amount_str = event["amount"]
        if not isinstance(amount_str, str) or not self._AMOUNT_RE.match(amount_str):
            raise ValueError("amount must be a positive decimal string with at most two fractional digits")

        try:
            amount_dec = Decimal(amount_str)
        except InvalidOperation:
            raise ValueError("invalid decimal amount")

        if amount_dec <= self._ZERO:
            raise ValueError("amount must be positive")

        event_copy = {
            "event_id": event_id,
            "payment_id": payment_id,
            "sequence": sequence,
            "type": event_type,
            "amount": amount_str,
        }

        # Check for duplicate or reused event_id
        if event_id in self._events_by_id:
            existing = self._events_by_id[event_id]
            if existing == event_copy:
                return "duplicate"
            raise ValueError("Reused event_id with different content")

        # Sequence rules per-payment
        next_sequence = self._payments[payment_id]["next_sequence"] if payment_id in self._payments else 1

        if sequence < next_sequence:
            raise ValueError("Reusing an already applied sequence with different content")

        buffered_for_payment = self._buffered.get(payment_id, {})
        if sequence in buffered_for_payment:
            raise ValueError("Reusing an already buffered sequence with different content")

        # Future events are buffered
        if sequence > next_sequence:
            if event_type == "authorized":
                raise ValueError("Sequence 1 must authorize; future sequences cannot authorize")
            if payment_id not in self._buffered:
                self._buffered[payment_id] = {}
            self._buffered[payment_id][sequence] = event_copy
            self._events_by_id[event_id] = event_copy
            return "buffered"

        # sequence == next_sequence: process event and drain consecutive buffered events atomically
        events_to_apply = [event_copy]
        curr_seq = sequence + 1
        while curr_seq in buffered_for_payment:
            events_to_apply.append(buffered_for_payment[curr_seq])
            curr_seq += 1

        # Simulate state changes
        if payment_id in self._payments:
            p = self._payments[payment_id]
            sim_payment = {
                "authorized": p["authorized"],
                "captured": p["captured"],
                "refunded": p["refunded"],
                "reversed": p["reversed"],
                "next_sequence": p["next_sequence"],
            }
        else:
            sim_payment = None

        for ev in events_to_apply:
            ev_seq = ev["sequence"]
            ev_type = ev["type"]
            ev_amt = Decimal(ev["amount"])

            if ev_seq == 1:
                if ev_type != "authorized":
                    raise ValueError("Sequence 1 must authorize")
                sim_payment = {
                    "authorized": ev_amt,
                    "captured": self._ZERO,
                    "refunded": self._ZERO,
                    "reversed": self._ZERO,
                    "next_sequence": 2,
                }
            else:
                if sim_payment is None:
                    raise ValueError("Payment must be authorized first")
                if ev_type == "authorized":
                    raise ValueError("Sequence 1 must authorize; subsequent sequences cannot authorize")
                elif ev_type == "captured":
                    if sim_payment["captured"] + ev_amt > sim_payment["authorized"]:
                        raise ValueError("Captures cannot exceed authorization")
                    sim_payment["captured"] += ev_amt
                elif ev_type == "refunded":
                    settled = sim_payment["captured"] - sim_payment["refunded"] - sim_payment["reversed"]
                    if ev_amt > settled:
                        raise ValueError("Refunds cannot exceed captured minus prior refunds and reversals")
                    sim_payment["refunded"] += ev_amt
                elif ev_type == "reversed":
                    settled = sim_payment["captured"] - sim_payment["refunded"] - sim_payment["reversed"]
                    if ev_amt > settled:
                        raise ValueError("Reversals follow the same remaining-settled limit")
                    sim_payment["reversed"] += ev_amt
                else:
                    raise ValueError("Unsupported transition")
                sim_payment["next_sequence"] = ev_seq + 1

        # Commit atomically
        self._payments[payment_id] = sim_payment
        self._events_by_id[event_id] = event_copy

        if len(events_to_apply) > 1:
            for drained_ev in events_to_apply[1:]:
                del self._buffered[payment_id][drained_ev["sequence"]]
            if not self._buffered[payment_id]:
                del self._buffered[payment_id]

        return "applied"

    def state(self, payment_id) -> dict | None:
        if not isinstance(payment_id, str) or payment_id not in self._payments:
            return None
        p = self._payments[payment_id]
        auth = p["authorized"]
        cap = p["captured"]
        ref = p["refunded"]
        rev = p["reversed"]
        avail = auth - cap
        balance = cap - ref - rev
        return {
            "authorized": str(auth.quantize(self._TWO_PLACES)),
            "captured": str(cap.quantize(self._TWO_PLACES)),
            "refunded": str(ref.quantize(self._TWO_PLACES)),
            "reversed": str(rev.quantize(self._TWO_PLACES)),
            "available_to_capture": str(avail.quantize(self._TWO_PLACES)),
            "merchant_balance": str(balance.quantize(self._TWO_PLACES)),
            "next_sequence": p["next_sequence"],
        }

    def snapshot(self) -> dict:
        return {pid: self.state(pid) for pid in sorted(self._payments.keys())}
