```python
class RetryableError(Exception):
    pass


class FatalError(Exception):
    pass


class CrashError(Exception):
    pass


class SagaOrchestrator:
    def __init__(
        self,
        executor,
        compensator,
        max_retries: int = 2,
        journal: dict | None = None,
    ):
        self.executor = executor
        self.compensator = compensator
        self.max_retries = max_retries
        if journal is None:
            journal = {}
        self.journal = journal

    def _validate(self, saga_id: str, steps: list[str]) -> None:
        if not isinstance(saga_id, str) or not saga_id:
            raise ValueError("saga_id must be a non-empty string")
        if not isinstance(steps, list) or len(steps) == 0:
            raise ValueError("steps must be a non-empty list of unique non-empty strings")
        for step in steps:
            if not isinstance(step, str) or not step:
                raise ValueError("Each step must be a non-empty string")
        if len(steps) != len(set(steps)):
            raise ValueError("Steps must be unique")
        if saga_id in self.journal:
            existing_steps = self.journal[saga_id].get("steps")
            if existing_steps is not None and existing_steps != steps:
                raise ValueError(f"Changed step plan for existing saga '{saga_id}'")

    def _execute_step(self, step: str) -> None:
        attempts = 0
        while True:
            try:
                self.executor(step)
                return
            except CrashError:
                raise
            except RetryableError:
                if attempts < self.max_retries:
                    attempts += 1
                    continue
                raise FatalError(f"Retries exhausted for step '{step}'")
            except FatalError:
                raise
            except Exception:
                raise FatalError(f"Non-declared exception during step '{step}'")

    def _compensate_step(self, step: str) -> None:
        attempts = 0
        while True:
            try:
                self.compensator(step)
                return
            except CrashError:
                raise
            except RetryableError:
                if attempts < self.max_retries:
                    attempts += 1
                    continue
                raise FatalError(f"Retries exhausted compensating step '{step}'")
            except FatalError:
                raise
            except Exception:
                raise FatalError(f"Non-declared exception compensating step '{step}'")

    def _compensate(self, saga_id: str, saga_record: dict) -> str:
        saga_record["status"] = "compensating"
        for step in reversed(saga_record["completed"]):
            if step in saga_record["compensated"]:
                continue
            self._compensate_step(step)
            saga_record["compensated"].append(step)
        saga_record["status"] = "compensated"
        return "compensated"

    def _run_or_recover(self, saga_id: str, steps: list[str]) -> str:
        self._validate(saga_id, steps)

        if saga_id not in self.journal:
            self.journal[saga_id] = {
                "steps": list(steps),
                "status": "executing",
                "completed": [],
                "compensated": [],
            }

        saga_record = self.journal[saga_id]
        if "steps" not in saga_record:
            saga_record["steps"] = list(steps)
        if "completed" not in saga_record:
            saga_record["completed"] = []
        if "compensated" not in saga_record:
            saga_record["compensated"] = []
        if "status" not in saga_record:
            saga_record["status"] = "executing"

        if saga_record["status"] == "compensated":
            return "compensated"

        if saga_record["status"] == "compensating":
            return self._compensate(saga_id, saga_record)

        if saga_record["status"] == "completed":
            return "completed"

        for step in steps:
            if step in saga_record["completed"]:
                continue
            try:
                self._execute_step(step)
                saga_record["completed"].append(step)
            except CrashError:
                raise
            except FatalError:
                return self._compensate(saga_id, saga_record)

        saga_record["status"] = "completed"
        return "completed"

    def run(self, saga_id: str, steps: list[str]) -> str:
        return self._run_or_recover(saga_id, steps)

    def recover(self, saga_id: str, steps: list[str]) -> str:
        return self._run_or_recover(saga_id, steps)
